type Item = { n: int, bucket = if n > 0 then 1 else 0, answer = bucket * 7 }
type Batch = { items: Item[], total = std.array.sum([x.answer for x in items]) }
input batch: Batch
output unrelated: Item = { n: 1 }
export output total: int = batch.total
export output probe: bool = unrelated != null
